import { PropsWithChildren, ReactNode } from 'react';

import { WithChildren } from '../../../../../core/types/with-children.js';
import { ChipAtom } from '../../tooltip-atoms/components/ChipAtom.js';
import { DurationChipAtom } from '../../tooltip-atoms/components/DurationChipAtom.js';
import { PrimaryAtom } from '../../tooltip-atoms/components/PrimaryAtom.js';
import { SecondaryAtom } from '../../tooltip-atoms/components/SecondaryAtom.js';
import { SymbolAtom } from '../../tooltip-atoms/components/SymbolAtom.js';
import { BubbleShape } from '../../tooltip-atoms/shapes/BubbleShape.js';
import { EmojiShape } from '../../tooltip-atoms/shapes/EmojiShape.js';
import { IconShape } from '../../tooltip-atoms/shapes/IconShape.js';
import { MultiDataPointShape } from '../../tooltip-atoms/shapes/MultiDataPointShape.js';
import { SingleDataPointShape } from '../../tooltip-atoms/shapes/SingleDataPointShape.js';
import { DurationChip } from '../ChartTooltip/components/DurationChip.js';
import { EventItem } from '../ChartTooltip/components/EventItem/EventItem.js';
import { GeoItem } from '../ChartTooltip/components/GeoItem.js';
import { KeyValue } from '../ChartTooltip/components/KeyValue.js';
import { SeriesItem } from '../ChartTooltip/components/SeriesItem/SeriesItem.js';
import { TextHeader } from '../ChartTooltip/components/TextHeader.js';
import { TimeFrameHeader } from '../ChartTooltip/components/TimeFrameHeader/TimeFrameHeader.js';
import { TooltipText } from '../section-components/atoms/TooltipText.js';
import { TooltipBody } from '../section-components/TooltipBody.js';
import { TooltipFooter } from '../section-components/TooltipFooter.js';
import { TooltipHeader } from '../section-components/TooltipHeader.js';
import { TooltipInfoContent } from '../section-components/TooltipInfoContent.js';
import { TooltipItem } from '../section-components/TooltipItem.js';
import { TooltipSubheader } from '../section-components/TooltipSubheader.js';
import { TooltipSymbolContent } from '../section-components/TooltipSymbolContent.js';
import { TooltipValueContent } from '../section-components/TooltipValueContent.js';

/**
 * @internal
 * Object exposing the slots config for the custom tooltip.
 * It contains:
 * - sections components (Header, Subheader, Body, Footer, Item): sections of the tooltip
 * - subsections components (Symbol, Content, Value): flex wrappers for the Item
 * - templates: wrappers for the tooltip atoms
 */
export const ChartTooltipSlots = {
  // section components
  Header: TooltipHeader,
  Subheader: TooltipSubheader,
  Body: TooltipBody,
  Item: TooltipItem,
  Footer: TooltipFooter,
  // Item subsections
  Symbol: TooltipSymbolContent,
  Content: TooltipInfoContent,
  Value: TooltipValueContent,
} as const;

/**
 * @internal
 * Object exposing the atoms the custom tooltip.
 * It contains:
 * - tooltip atoms
 * - tooltip shapes
 */
export const ChartTooltipAtoms = {
  // atoms
  Chip: ChipAtom,
  DurationChipAtom,
  Primary: PrimaryAtom,
  Secondary: SecondaryAtom,
  Symbol: SymbolAtom,
  // shapes
  Bubble: BubbleShape,
  Emoji: EmojiShape,
  Icon: IconShape,
  MultiDataPoint: MultiDataPointShape,
  SingleDataPoint: SingleDataPointShape,
} as const;

/**
 * @internal
 * Object exposing the templates for the custom tooltip
 */
export const ChartTooltipTemplate = {
  GeoItem,
  Text: TooltipText,
  SeriesItem,
  TimeFrameHeader,
  TextHeader,
  EventItem,
  KeyValue,
  DurationChip,
};

/** @internal */
export type ChartTooltipSlotsType = typeof ChartTooltipSlots;
/** @internal */
export type ChartTooltipAtomsType = typeof ChartTooltipAtoms;
/** @internal */
export type ChartTooltipTemplateType = typeof ChartTooltipTemplate;

export type TooltipHeaderProps = PropsWithChildren<
  React.HTMLAttributes<HTMLDivElement>
>;

/**
 * Function that provides the estimated height for the item virtualization used in the `TooltipBody`.
 */
export type VirtualEstimatedSize = (index: number) => number;

export type TooltipFooterProps = PropsWithChildren<
  React.HTMLAttributes<HTMLDivElement>
>;

export interface TooltipBodyProps
  extends React.HTMLAttributes<HTMLDivElement>,
    WithChildren {
  /**
   * Toggles virtualization of tooltip body content, which is used to improve performance.
   * @defaultValue true
   */
  virtualization?: boolean;
  /**
   * Used in combination with the `virtualization` prop. This estimated item height is used to ensure features like smooth-scrolling work correctly.
   */
  itemHeight?: VirtualEstimatedSize;
}

export interface TooltipItemProps
  extends React.HTMLAttributes<HTMLDivElement>,
    WithChildren {
  /**
   * Indicates if the tooltip has a divider
   * @defaultValue false
   */
  showDivider?: boolean;
  actions?: () => React.ReactElement;
}

export interface TooltipValueProps
  extends React.HTMLAttributes<HTMLDivElement>,
    WithChildren {
  /**
   * Indicates the variant for the value
   * @defaultValue secondary
   */
  variant?: 'secondary' | 'chip';
}

export interface TooltipDurationProps
  extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * The starting date.
   */
  from: Date;
  /**
   * The end date.
   */
  to: Date;
}

export interface TooltipTextProps
  extends React.HTMLAttributes<HTMLDivElement>,
    WithChildren {
  /**
   * Indicates the variant for the text
   * @defaultValue primary
   */
  variant?: 'primary' | 'secondary';
  /**
   * Available modes for how overly long text is truncated and where the ellipsis is placed.
   * @defaultValue middle
   */
  truncationMode?: 'start' | 'middle' | 'end';
}

export interface TooltipIndicatorProps
  extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Indicates the style for the datapoint
   * @defaultValue single
   */
  variant?: 'single' | 'multi' | 'bubble';
  /**
   * Indicates if the datapoint is in active state.
   */
  active?: boolean;
  /**
   * Color for the datapoint.
   */
  color: string;
}

export interface TooltipEmojiProps
  extends React.HTMLAttributes<HTMLDivElement>,
    WithChildren {
  /**
   * Indicates if the emoji is in active state.
   */
  active?: boolean;
  /**
   * Aria label for the emoji.
   */
  label?: string;
}

export interface TooltipItemSlots {
  symbolSection?: ReactNode;
  infoSection?: ReactNode;
  valueSection?: ReactNode;
}
